const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Asir region in Saudi Arabia. Using a point in Abha, a major city in Asir province.
  const geometry = ee.Geometry.Point(42.56, 18.21); // Coordinates for Abha, Asir

  const startMonth = 6; // June
  const endMonth = 6;   // June

  // Specific comparison years
  const year2016 = 2016;
  const year2017 = 2017;

  // Long-term average period
  const ltStartYear = 2003;
  const ltEndYear = 2011;

  const scale = 1000; // MODIS 250m, using 1000m scale for regional average to avoid memory issues.

  // Function to filter MODIS MOD13Q1 collection by month and year range, and mask clouds.
  const getNdviCollection = (startYear, endYear, startMonth, endMonth) => {
    let collection = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterBounds(geometry);

    // Filter for specific month(s) across the year range
    const filteredByMonth = ee.ImageCollection(
      ee.List.sequence(startYear, endYear).map(year => {
        const start = ee.Date.fromYMD(year, startMonth, 1);
        const end = ee.Date.fromYMD(year, endMonth, 1).advance(1, 'month');
        return collection.filterDate(start, end);
      }).flatten()
    );

    // Function to mask bad quality pixels
    const maskBadQuality = (image) => {
      const quality = image.select('VI_Quality');
      // Values for good quality:
      // 0: Good data, use with confidence
      // 1: Marginal data, useful but look at other QC information
      // Bits 2-5 are for VI usefulness. Bits 0-1 are MODLAND QA.
      // Only keep pixels where VI_Quality indicates good data (0) or marginal (1).
      const goodQuality = quality.bitwiseAnd(3).lte(1); // MODLAND_QA_bits 0-1

      // Also filter based on pixel reliability:
      // 0: Good data, use with confidence
      // 1: Marginal data, useful but look at other QC information
      // 2: TBD, fill value
      // 3: Pixel not produced, fill value
      const pixelReliability = image.select('250m_16_days_pixel_reliability');
      const reliable = pixelReliability.lte(1); // 0 or 1

      // Return the NDVI band, scaled, and masked
      return image.select('NDVI')
        .updateMask(goodQuality.and(reliable))
        .divide(10000) // Scale NDVI values
        .copyProperties(image, ['system:time_start']);
    };

    return filteredByMonth.map(maskBadQuality);
  };

  // Get 2016 data
  const col2016 = getNdviCollection(year2016, year2016, startMonth, endMonth);
  const size2016 = col2016.size().getInfo();
  if (size2016 === 0) {
    console.log(`No images found for June ${year2016}.`);
    console.log("C1");
    return;
  }
  const meanNdvi2016 = col2016.mean();

  // Get 2017 data
  const col2017 = getNdviCollection(year2017, year2017, startMonth, endMonth);
  const size2017 = col2017.size().getInfo();
  if (size2017 === 0) {
    console.log(`No images found for June ${year2017}.`);
    console.log("C1");
    return;
  }
  const meanNdvi2017 = col2017.mean();

  // Get long-term average data
  const ltCollection = getNdviCollection(ltStartYear, ltEndYear, startMonth, endMonth);
  const sizeLT = ltCollection.size().getInfo();
  if (sizeLT === 0) {
    console.log(`No images found for long-term average (June ${ltStartYear}-${ltEndYear}).`);
    console.log("C1");
    return;
  }
  const meanNdviLT = ltCollection.mean();

  // 3. Processing and Calculation
  const getRegionalMean = async (image, name) => {
    if (!image) { // Check if image is potentially null due to empty collection
      return null;
    }
    const reducer = ee.Reducer.mean();
    const result = await image.reduceRegion({
      reducer: reducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    // Calculate valid pixel count
    const pixelCount = await image.select('NDVI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${name}.`);
      return { value: null, pixels: 0 };
    }
    return { value: result, pixels: pixelCount };
  };

  const result2016 = await getRegionalMean(meanNdvi2016, `June ${year2016}`);
  const result2017 = await getRegionalMean(meanNdvi2017, `June ${year2017}`);
  const resultLT = await getRegionalMean(meanNdviLT, `June ${ltStartYear}-${ltEndYear} Average`);

  if (!result2016 || !result2017 || !resultLT || result2016.pixels === 0 || result2017.pixels === 0 || resultLT.pixels === 0) {
    console.log("C2");
    return;
  }

  const ndvi2016 = result2016.value;
  const ndvi2017 = result2017.value;
  const ndviLT = resultLT.value;

  if (ndvi2016 === null || ndvi2017 === null || ndviLT === null || isNaN(ndvi2016) || isNaN(ndvi2017) || isNaN(ndviLT)) {
    console.log("C3");
    return;
  }

  console.log(`Images June ${year2016}: ${size2016}, Pixels: ${result2016.pixels}, NDVI: ${ndvi2016.toFixed(3)}`);
  console.log(`Images June ${year2017}: ${size2017}, Pixels: ${result2017.pixels}, NDVI: ${ndvi2017.toFixed(3)}`);
  console.log(`Images June ${ltStartYear}-${ltEndYear}: ${sizeLT}, Pixels: ${resultLT.pixels}, NDVI: ${ndviLT.toFixed(3)}`);

  const higher2016 = ndvi2016 > ndviLT;
  const higher2017 = ndvi2017 > ndviLT;

  if (higher2016 && higher2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
